def parse_ini(text):
    """Sections, keys and values of INI text. See TASK.md."""
    result = {}
    current_section = ""
    current_key = None

    lines = text.split('\n')

    for line_num, line in enumerate(lines, 1):
        # Rule 1: Drop \r before \n
        if line.endswith('\r'):
            line = line[:-1]

        # Get the stripped version for checking
        stripped = line.lstrip()

        # Rule 2: Skip blank lines and comments
        if not stripped or stripped[0] in (';', '#'):
            current_key = None
            continue

        # Rule 7: Check if it's a continuation line
        if line and line[0] in (' ', '\t'):
            if current_key is None:
                raise ValueError(f"line {line_num}")
            # Ensure the current section exists
            if current_section not in result:
                result[current_section] = {}
            result[current_section][current_key] += '\n' + stripped
            continue

        current_key = None  # Reset for non-continuation lines

        # Rule 3: Section header
        if stripped.startswith('['):
            if not stripped.endswith(']'):
                raise ValueError(f"line {line_num}")
            section_name = stripped[1:-1].strip()
            if not section_name:
                raise ValueError(f"line {line_num}")
            current_section = section_name
            if section_name not in result:
                result[section_name] = {}
            continue

        # Rule 4: key = value
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip().lower()
            value = value.strip()
            if not key:
                raise ValueError(f"line {line_num}")
            if current_section not in result:
                result[current_section] = {}
            result[current_section][key] = value
            current_key = key
            continue

        # Rule 10: Any other line is an error
        raise ValueError(f"line {line_num}")

    # Rule 6: Remove empty "" section if it has no keys
    if "" in result and not result[""]:
        del result[""]

    return result
